dashboard.definition:
{
 "title": "Wireless Overview",
 "description": "One WLC: clients and APs, SSIDs and PHY types, access points with their radios, per-band utilization, noise and interference of the busiest AP, CPU and memory.",
 "inputs": {
  "input_time": {
   "type": "input.timerange",
   "title": "Time range",
   "options": {
    "token": "global_time",
    "defaultValue": "-4h@m,now"
   }
  },
  "input_wlc": {
   "type": "input.dropdown",
   "title": "WLC",
   "dataSources": {
    "primary": "ds_wlc"
   },
   "options": {
    "token": "wlc",
    "selectFirstSearchResult": true,
    "items": ">frame(label, value) | objects()"
   },
   "context": {
    "label": ">primary | seriesByName(\"wlc\") | renameSeries(\"label\")",
    "value": ">primary | seriesByName(\"wlc\") | renameSeries(\"value\")"
   }
  }
 },
 "defaults": {
  "dataSources": {
   "ds.search": {
    "options": {
     "queryParameters": {
      "earliest": "$global_time.earliest$",
      "latest": "$global_time.latest$"
     },
     "refresh": "90s",
     "refreshType": "delay"
    }
   }
  }
 },
 "visualizations": {
  "viz_clients_now": {
   "type": "splunk.singlevalue",
   "title": "Connected clients (last 15 min)",
   "dataSources": {
    "primary": "ds_clients_now"
   },
   "options": {
    "majorColor": "#708794"
   }
  },
  "viz_aps": {
   "type": "splunk.singlevalue",
   "title": "APs joined (last 15 min)",
   "dataSources": {
    "primary": "ds_aps_joined"
   },
   "options": {
    "majorColor": "> primary | seriesByName(\"short\") | lastPoint() | rangeValue(shortColors)",
    "majorValue": "> primary | seriesByName(\"aps\")"
   },
   "context": {
    "shortColors": [
     {
      "to": 1,
      "value": "#708794"
     },
     {
      "from": 1,
      "value": "#dc4e41"
     }
    ]
   }
  },
  "viz_cpu_now": {
   "type": "splunk.singlevalue",
   "title": "WLC CPU (last 15 min)",
   "dataSources": {
    "primary": "ds_cpu_now"
   },
   "options": {
    "majorColor": "#708794",
    "unit": "%",
    "unitPosition": "after"
   }
  },
  "viz_mem_now": {
   "type": "splunk.singlevalue",
   "title": "WLC memory (last 15 min)",
   "dataSources": {
    "primary": "ds_mem_now"
   },
   "options": {
    "majorColor": "#708794",
    "unit": "%",
    "unitPosition": "after",
    "numberPrecision": 1
   }
  },
  "viz_ssids": {
   "type": "splunk.table",
   "title": "SSIDs and their clients (last 15 min)",
   "dataSources": {
    "primary": "ds_ssids"
   },
   "options": {
    "count": 10
   },
   "showProgressBar": true
  },
  "viz_phy": {
   "type": "splunk.bar",
   "title": "Clients by PHY (last 15 min)",
   "dataSources": {
    "primary": "ds_phy"
   },
   "options": {
    "legendDisplay": "off"
   },
   "showProgressBar": true
  },
  "viz_ap_table": {
   "type": "splunk.table",
   "title": "Access points (last 15 min): radio = channel / width / TX power",
   "dataSources": {
    "primary": "ds_ap_table"
   },
   "options": {
    "count": 20,
    "columnFormat": {
     "State": {
      "rowBackgroundColors": "> table | seriesByName(\"State\") | matchValue(stateColors)"
     }
    }
   },
   "showProgressBar": true,
   "context": {
    "stateColors": [
     {
      "match": "registered",
      "value": "#53a051"
     },
     {
      "match": "not joined",
      "value": "#dc4e41"
     }
    ]
   }
  },
  "viz_clients": {
   "type": "splunk.area",
   "title": "Clients by band",
   "dataSources": {
    "primary": "ds_clients"
   },
   "options": {
    "stackMode": "stacked",
    "seriesColorsByField": {
     "2.4 GHz": "#1e93c6",
     "5 GHz": "#f2b827",
     "6 GHz": "#d6563c"
    },
    "legendDisplay": "bottom"
   },
   "showProgressBar": true
  },
  "viz_sys": {
   "type": "splunk.line",
   "title": "WLC CPU and memory %",
   "dataSources": {
    "primary": "ds_sys"
   },
   "options": {
    "legendDisplay": "bottom",
    "yAxisMin": 0
   },
   "showProgressBar": true
  },
  "viz_tx": {
   "type": "splunk.line",
   "title": "TX utilization by band, busiest AP",
   "dataSources": {
    "primary": "ds_tx"
   },
   "options": {
    "seriesColorsByField": {
     "2.4 GHz": "#1e93c6",
     "5 GHz": "#f2b827",
     "6 GHz": "#d6563c"
    },
    "legendDisplay": "bottom",
    "nullValueDisplay": "connect"
   },
   "showProgressBar": true
  },
  "viz_rx": {
   "type": "splunk.line",
   "title": "RX utilization by band, busiest AP",
   "dataSources": {
    "primary": "ds_rx"
   },
   "options": {
    "seriesColorsByField": {
     "2.4 GHz": "#1e93c6",
     "5 GHz": "#f2b827",
     "6 GHz": "#d6563c"
    },
    "legendDisplay": "bottom",
    "nullValueDisplay": "connect"
   },
   "showProgressBar": true
  },
  "viz_noise": {
   "type": "splunk.line",
   "title": "Noise channel utilization by band, worst AP",
   "dataSources": {
    "primary": "ds_noise"
   },
   "options": {
    "seriesColorsByField": {
     "2.4 GHz": "#1e93c6",
     "5 GHz": "#f2b827",
     "6 GHz": "#d6563c"
    },
    "legendDisplay": "bottom",
    "nullValueDisplay": "connect"
   },
   "showProgressBar": true
  },
  "viz_nonwifi": {
   "type": "splunk.line",
   "title": "Non-WiFi interference by band, worst AP",
   "dataSources": {
    "primary": "ds_nonwifi"
   },
   "options": {
    "seriesColorsByField": {
     "2.4 GHz": "#1e93c6",
     "5 GHz": "#f2b827",
     "6 GHz": "#d6563c"
    },
    "legendDisplay": "bottom",
    "nullValueDisplay": "connect"
   },
   "showProgressBar": true
  }
 },
 "dataSources": {
  "ds_wlc": {
   "type": "ds.search",
   "name": "wlc",
   "options": {
    "query": "| mcatalog values(extracted_source) as wlc WHERE index=cisco_metrics metric_name=mdt_wl_info_ap_ip_addr | mvexpand wlc"
   }
  },
  "ds_clients_now": {
   "type": "ds.search",
   "name": "clients_now",
   "options": {
    "query": "| mstats latest(mdt_wl_ap_stats_num_assoc_clients) as c WHERE index=cisco_metrics extracted_source=\"$wlc$\" span=1m BY ssid_counters_wtp_mac ssid_counters_slot_id ssid_counters_wlan_id | where _time + 60 <= now() | stats sum(c) as c by _time | stats latest(c) as clients",
    "queryParameters": {
     "earliest": "-15m",
     "latest": "now"
    }
   }
  },
  "ds_aps": {
   "type": "ds.search",
   "name": "aps",
   "options": {
    "query": "| mstats latest(_value) WHERE index=cisco_metrics extracted_source=\"$wlc$\" metric_name=mdt_wl_info_eth_mac BY eth_mac ap_name_mac_map_wtp_name | join type=left eth_mac [| mstats latest(_value) WHERE index=cisco_metrics extracted_source=\"$wlc$\" metric_name=mdt_wl_info_wtp_mac BY ethernet_mac_wtp_mac_map_ethernet_mac wtp_mac | rename ethernet_mac_wtp_mac_map_ethernet_mac as eth_mac | fields eth_mac wtp_mac] | join type=left wtp_mac [| mstats latest(_value) WHERE index=cisco_metrics extracted_source=\"$wlc$\" metric_name=mdt_wl_info_ap_ip_addr BY oper_data_wtp_mac ap_ip_addr | where ap_ip_addr!=\"0.0.0.0\" | rename oper_data_wtp_mac as wtp_mac | fields wtp_mac ap_ip_addr] | join type=left wtp_mac [| mstats latest(_value) WHERE index=cisco_metrics extracted_source=\"$wlc$\" metric_name=mdt_wl_info_ap_operation_state BY capwap_data_wtp_mac ap_operation_state | rename capwap_data_wtp_mac as wtp_mac | fields wtp_mac ap_operation_state] | join type=left wtp_mac [| mstats latest(_value) WHERE index=cisco_metrics extracted_source=\"$wlc$\" metric_name=mdt_wl_info_location BY capwap_data_wtp_mac location | where location!=\"default location\" | rename capwap_data_wtp_mac as wtp_mac | fields wtp_mac location] | join type=left eth_mac [| mstats latest_time(_value) as t WHERE index=cisco_metrics extracted_source=\"$wlc$\" metric_name=mdt_wl_client_stats_ap_mac_address BY dot11_oper_data_ms_mac_address ap_mac_address | sort 0 - t | dedup dot11_oper_data_ms_mac_address | stats count as clients by ap_mac_address | rename ap_mac_address as eth_mac] | join type=left wtp_mac [| mstats latest(mdt_wl_radio_info_curr_freq) as ch latest(mdt_wl_radio_info_chan_width) as w WHERE index=cisco_metrics extracted_source=\"$wlc$\" BY radio_oper_data_wtp_mac radio_oper_data_radio_slot_id | join type=left radio_oper_data_wtp_mac radio_oper_data_radio_slot_id [| mstats latest(mdt_wl_radio_info_curr_tx_power_in_dbm) as p WHERE index=cisco_metrics extracted_source=\"$wlc$\" BY radio_oper_data_wtp_mac radio_oper_data_radio_slot_id radio_band_info_band_id | where radio_band_info_band_id=radio_oper_data_radio_slot_id | fields - radio_band_info_band_id] | join type=left radio_oper_data_wtp_mac radio_oper_data_radio_slot_id [| mstats latest(_value) WHERE index=cisco_metrics extracted_source=\"$wlc$\" metric_name=mdt_wl_radio_info_oper_state BY radio_oper_data_wtp_mac radio_oper_data_radio_slot_id oper_state | fields - latest*] | eval cell=if(isnotnull(oper_state) AND oper_state!=\"radio-up\", \"down\", \"ch \".ch.\" / \".w.\" MHz\".if(isnotnull(p), \" / \".p.\" dBm\", \"\")), col=\"Radio \".radio_oper_data_radio_slot_id | xyseries radio_oper_data_wtp_mac col cell | rename radio_oper_data_wtp_mac as wtp_mac] | eval State=coalesce(ap_operation_state, \"not joined\")",
    "queryParameters": {
     "earliest": "-15m",
     "latest": "now"
    }
   }
  },
  "ds_sys_now": {
   "type": "ds.search",
   "name": "sys_now",
   "options": {
    "query": "| mstats latest(mdt_xe_mem_stats_used_memory) as used latest(mdt_xe_mem_stats_total_memory) as total WHERE index=cisco_metrics extracted_source=\"$wlc$\" span=1m BY memory_statistic_name | stats sum(used) as used sum(total) as total by _time | join type=left _time [| mstats avg(mdt_xe_cpu_stats_one_minute) as cpu WHERE index=cisco_metrics extracted_source=\"$wlc$\" span=1m] | where _time + 60 <= now() | eval \"CPU %\"=round(cpu, 0), \"Memory %\"=round(used / total * 100, 1) | fields _time \"CPU %\" \"Memory %\"",
    "queryParameters": {
     "earliest": "-15m",
     "latest": "now"
    }
   }
  },
  "ds_ssids": {
   "type": "ds.search",
   "name": "ssids",
   "options": {
    "query": "| mstats latest(_value) WHERE index=cisco_metrics extracted_source=\"$wlc$\" metric_name=mdt_wl_info_ssid BY ssid | eval Clients=0 | append [| mstats latest(_value) WHERE index=cisco_metrics extracted_source=\"$wlc$\" metric_name=mdt_wl_info_vap_ssid BY vap_ssid dot11_oper_data_ms_mac_address | stats dc(dot11_oper_data_ms_mac_address) as Clients by vap_ssid | rename vap_ssid as ssid] | stats max(Clients) as Clients by ssid | rename ssid as SSID | sort 0 - Clients SSID",
    "queryParameters": {
     "earliest": "-15m",
     "latest": "now"
    }
   }
  },
  "ds_phy": {
   "type": "ds.search",
   "name": "phy",
   "options": {
    "query": "| mstats latest_time(_value) as t WHERE index=cisco_metrics extracted_source=\"$wlc$\" metric_name=mdt_wl_info_ewlc_ms_phy_type BY dot11_oper_data_ms_mac_address ewlc_ms_phy_type | sort 0 - t | dedup dot11_oper_data_ms_mac_address | eval PHY=replace(ewlc_ms_phy_type, \"^client-dot11([a-z]+).*\", \"802.11\\1\") | stats count as Clients by PHY | sort PHY",
    "queryParameters": {
     "earliest": "-15m",
     "latest": "now"
    }
   }
  },
  "ds_clients": {
   "type": "ds.search",
   "name": "clients",
   "options": {
    "query": "| mstats latest(mdt_wl_ap_stats_num_assoc_clients) as c WHERE index=cisco_metrics extracted_source=\"$wlc$\" span=1m BY ssid_counters_wtp_mac ssid_counters_slot_id ssid_counters_wlan_id | where _time + 60 <= now() | stats sum(c) as c by _time ssid_counters_slot_id | eval band=case(ssid_counters_slot_id=0, \"2.4 GHz\", ssid_counters_slot_id=1, \"5 GHz\", ssid_counters_slot_id=2, \"6 GHz\") | timechart avg(c) as c by band | fillnull value=0"
   }
  },
  "ds_sys": {
   "type": "ds.search",
   "name": "sys",
   "options": {
    "query": "| mstats latest(mdt_xe_mem_stats_used_memory) as used latest(mdt_xe_mem_stats_total_memory) as total WHERE index=cisco_metrics extracted_source=\"$wlc$\" span=1m BY memory_statistic_name | stats sum(used) as used sum(total) as total by _time | join type=left _time [| mstats avg(mdt_xe_cpu_stats_one_minute) as cpu WHERE index=cisco_metrics extracted_source=\"$wlc$\" span=1m] | where _time + 60 <= now() | eval \"CPU %\"=round(cpu, 0), \"Memory %\"=round(used / total * 100, 1) | fields _time \"CPU %\" \"Memory %\""
   }
  },
  "ds_rf": {
   "type": "ds.search",
   "name": "rf",
   "options": {
    "query": "| mstats max(mdt_wl_ap_stats_tx_util_percentage) as tx max(mdt_wl_ap_stats_rx_util_percentage) as rx max(mdt_wl_ap_stats_rx_noise_channel_utilization) as noise max(mdt_wl_ap_stats_non_wifi_inter) as nonwifi WHERE index=cisco_metrics extracted_source=\"$wlc$\" span=1m BY rrm_measurement_radio_slot_id | where _time + 60 <= now() | eval band=case(rrm_measurement_radio_slot_id=0, \"2.4 GHz\", rrm_measurement_radio_slot_id=1, \"5 GHz\", rrm_measurement_radio_slot_id=2, \"6 GHz\")"
   }
  },
  "ds_cpu_now": {
   "type": "ds.chain",
   "name": "cpu_now",
   "options": {
    "extend": "ds_sys_now",
    "query": "| stats latest(\"CPU %\") as cpu"
   }
  },
  "ds_mem_now": {
   "type": "ds.chain",
   "name": "mem_now",
   "options": {
    "extend": "ds_sys_now",
    "query": "| stats latest(\"Memory %\") as mem"
   }
  },
  "ds_aps_joined": {
   "type": "ds.chain",
   "name": "aps_joined",
   "options": {
    "extend": "ds_aps",
    "query": "| stats count as total count(eval(State==\"registered\")) as joined | eval aps=joined.\" / \".total, short=total - joined"
   }
  },
  "ds_ap_table": {
   "type": "ds.chain",
   "name": "ap_table",
   "options": {
    "extend": "ds_aps",
    "query": "| foreach \"Radio *\" [eval <<FIELD>>=if(State==\"registered\", '<<FIELD>>', null())] | fillnull value=0 clients | rename ap_name_mac_map_wtp_name as AP, ap_ip_addr as IP, location as Location, clients as Clients | sort AP | table AP IP State Location Clients \"Radio *\""
   }
  },
  "ds_tx": {
   "type": "ds.chain",
   "name": "tx",
   "options": {
    "extend": "ds_rf",
    "query": "| timechart max(tx) by band"
   }
  },
  "ds_rx": {
   "type": "ds.chain",
   "name": "rx",
   "options": {
    "extend": "ds_rf",
    "query": "| timechart max(rx) by band"
   }
  },
  "ds_noise": {
   "type": "ds.chain",
   "name": "noise",
   "options": {
    "extend": "ds_rf",
    "query": "| timechart max(noise) by band"
   }
  },
  "ds_nonwifi": {
   "type": "ds.chain",
   "name": "nonwifi",
   "options": {
    "extend": "ds_rf",
    "query": "| timechart max(nonwifi) by band"
   }
  }
 },
 "layout": {
  "type": "grid",
  "globalInputs": [
   "input_time",
   "input_wlc"
  ],
  "layoutDefinitions": {
   "layout_1": {
    "type": "grid",
    "options": {
     "width": 1440,
     "height": 1550
    },
    "structure": [
     {
      "item": "viz_clients_now",
      "type": "block",
      "position": {
       "x": 0,
       "y": 0,
       "w": 360,
       "h": 130
      }
     },
     {
      "item": "viz_aps",
      "type": "block",
      "position": {
       "x": 360,
       "y": 0,
       "w": 360,
       "h": 130
      }
     },
     {
      "item": "viz_cpu_now",
      "type": "block",
      "position": {
       "x": 720,
       "y": 0,
       "w": 360,
       "h": 130
      }
     },
     {
      "item": "viz_mem_now",
      "type": "block",
      "position": {
       "x": 1080,
       "y": 0,
       "w": 360,
       "h": 130
      }
     },
     {
      "item": "viz_clients",
      "type": "block",
      "position": {
       "x": 0,
       "y": 130,
       "w": 720,
       "h": 300
      }
     },
     {
      "item": "viz_ssids",
      "type": "block",
      "position": {
       "x": 720,
       "y": 130,
       "w": 360,
       "h": 300
      }
     },
     {
      "item": "viz_phy",
      "type": "block",
      "position": {
       "x": 1080,
       "y": 130,
       "w": 360,
       "h": 300
      }
     },
     {
      "item": "viz_ap_table",
      "type": "block",
      "position": {
       "x": 0,
       "y": 430,
       "w": 1440,
       "h": 260
      }
     },
     {
      "item": "viz_tx",
      "type": "block",
      "position": {
       "x": 0,
       "y": 690,
       "w": 720,
       "h": 300
      }
     },
     {
      "item": "viz_rx",
      "type": "block",
      "position": {
       "x": 720,
       "y": 690,
       "w": 720,
       "h": 300
      }
     },
     {
      "item": "viz_noise",
      "type": "block",
      "position": {
       "x": 0,
       "y": 990,
       "w": 720,
       "h": 300
      }
     },
     {
      "item": "viz_nonwifi",
      "type": "block",
      "position": {
       "x": 720,
       "y": 990,
       "w": 720,
       "h": 300
      }
     },
     {
      "item": "viz_sys",
      "type": "block",
      "position": {
       "x": 0,
       "y": 1290,
       "w": 1440,
       "h": 260
      }
     }
    ]
   }
  },
  "tabs": {
   "items": [
    {
     "label": "WLC",
     "layoutId": "layout_1"
    }
   ]
  }
 },
 "applicationProperties": {}
}
